import Link from "next/link";

export function CtaBanner({
  title = "Ready to Deliver This Level of Work Under Your Brand?",
  subtitle = "Partner with Boldteq as your dedicated backend delivery team and gain a reliable, scalable foundation for your technology initiatives.",
  primaryCta = { label: "Book a Demo", href: "/book-a-demo" },
  secondaryCta = { label: "View Plans", href: "/pricing" },
}: {
  title?: string;
  subtitle?: string;
  primaryCta?: { label: string; href: string };
  secondaryCta?: { label: string; href: string };
}) {
  return (
    <section
      style={{
        backgroundColor: "transparent",
        marginBottom: "70px",
        padding: "0 5%",
        position: "relative",
      }}
    >
      <div
        style={{
          backgroundColor: "#082753",
          backgroundImage: "url('/images/webflow/Mask-group-1.png')",
          backgroundPosition: "100% 100%",
          backgroundRepeat: "no-repeat",
          backgroundSize: "auto",
          borderRadius: "20px",
          padding: "40px 20px 50px",
          maxWidth: "1280px",
          margin: "0 auto",
          textAlign: "center",
        }}
      >
        <h2
          style={{
            color: "#ffffff",
            fontFamily: "'Roobert PRO', Arial, sans-serif",
            fontSize: "40px",
            fontWeight: 700,
            lineHeight: "45px",
            margin: "0",
          }}
        >
          {title}
        </h2>

        {subtitle && (
          <p
            style={{
              color: "rgba(255, 255, 255, 0.7)",
              fontFamily: "'Roobert PRO', Arial, sans-serif",
              fontSize: "16px",
              lineHeight: "28px",
              marginTop: "16px",
              maxWidth: "600px",
              marginLeft: "auto",
              marginRight: "auto",
            }}
          >
            {subtitle}
          </p>
        )}

        <div
          style={{
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            gap: "12px",
            marginTop: "32px",
            flexWrap: "wrap",
          }}
        >
          <Link
            href={primaryCta.href}
            style={{
              background: "linear-gradient(90deg, #21cfff, #019ae6)",
              color: "#fff",
              borderRadius: "999px",
              padding: "12px 28px",
              fontWeight: 700,
              fontSize: "16px",
              fontFamily: "'Roobert PRO', Arial, sans-serif",
              textDecoration: "none",
              display: "inline-flex",
              alignItems: "center",
              gap: "8px",
            }}
          >
            {primaryCta.label}
          </Link>

          <Link
            href={secondaryCta.href}
            style={{
              background: "transparent",
              color: "#fff",
              border: "1px solid rgba(255, 255, 255, 0.3)",
              borderRadius: "999px",
              padding: "12px 28px",
              fontWeight: 700,
              fontSize: "16px",
              fontFamily: "'Roobert PRO', Arial, sans-serif",
              textDecoration: "none",
              display: "inline-flex",
              alignItems: "center",
            }}
          >
            {secondaryCta.label}
          </Link>
        </div>
      </div>
    </section>
  );
}
